<script setup>
import { onMounted, onUnmounted, ref } from 'vue'
import request from '../api/request.js'
import { useDelivery } from './useDelivery.js'
import BacktestReport from './BacktestReport.vue'
const developer = new URLSearchParams(location.search).get('developer') === '1'
const props = defineProps({ id:String })
const emit = defineEmits(['started'])
const packages = ref([]), packageError = ref('')
const form = ref({package_id:null,pe_max:30,roe_min:15,rev_yoy_min:null,cost_pct_per_side:.13,initial_cash:1000000,risk_free_annual_pct:2})
const { data,error,busy,load,submit,resume,dispose } = useDelivery(v => emit('started',v))
const reproduction = ref(null), reproducing = ref(false), reproductionError = ref('')
async function reproduce() { reproducing.value = true; reproductionError.value = ''; try { reproduction.value = await request('/quant/deliveries/' + data.value.run_id + '/reproduce',{method:'POST',timeoutMs:130000}) } catch(e) { reproductionError.value = e.message } finally { reproducing.value = false } }
async function loadPackages() { try { packages.value = await request('/quant/strategies/packages'); packageError.value = '' } catch(e) { packageError.value = e.message } }
async function run() { const values = {...form.value}; for (const k of ['pe_max','roe_min','rev_yoy_min']) if (values[k] === '') values[k] = null; await submit('strategies',values) }
onMounted(async () => { await loadPackages(); if (props.id) { await load(props.id); if (data.value?.request) form.value = {...data.value.request} } })
onUnmounted(dispose)
</script>
<template><div class="page backtest-page"><section class="panel panel-pad bt-header"><div class="section-heading"><h1>年度选股 · 完整策略回测</h1><a v-if="developer" class="btn" href="#/backtest">历史数据取证工作台</a></div>
  <p class="condition-note">独立执行年度选股、原始价格成交、公司行为账本与三种成本。必须绑定服务端审核包；暂未接入时保存具体缺项，功能可随合格数据包接入直接执行。</p>
  <div class="bt-form"><div class="bt-field"><label for="strategy-package">冻结历史数据包</label><select id="strategy-package" v-model="form.package_id"><option :value="null">{{ packages.length ? '请选择历史包' : '尚未接入完整历史包' }}</option><option v-for="p in packages" :key="p.id" :value="p.id" :disabled="p.status === 'INVALID'">{{ p.id }} · {{ p.start }} ~ {{ p.end }}</option></select></div><div v-for="field in [{key:'pe_max',label:'PE 上限'},{key:'roe_min',label:'ROE 下限（%）'},{key:'rev_yoy_min',label:'营收同比下限（%，可空）'},{key:'cost_pct_per_side',label:'单侧成本（%）'},{key:'initial_cash',label:'初始现金（元）'},{key:'risk_free_annual_pct',label:'年无风险收益假设（%）'}]" :key="field.key" class="bt-field"><label :for="'strategy-' + field.key">{{ field.label }}</label><input :id="'strategy-' + field.key" v-model="form[field.key]" type="number" step="any" /></div></div>
  <p v-if="packageError" class="error-text" role="alert">{{ packageError }}</p>
  <div class="bt-actions"><button class="btn btn-primary" :disabled="busy || data?.status === 'RUNNING'" @click="run">{{ data?.status === 'RUNNING' ? '正在准入检查与隔离计算…' : '确认条件并执行完整回测' }}</button><button class="btn" @click="loadPackages">刷新接入包</button><a v-if="developer" class="btn" href="#/delivery">查看接入合同与完整演示路径</a></div>
  <p v-if="error || data?.error" class="error-text" role="alert">{{ error || data.error }}</p>
  <div v-if="data" class="bt-actions"><button class="btn" @click="load(data.run_id)">刷新结果</button><button v-if="['FAILED','INTERRUPTED'].includes(data.status)" class="btn" :disabled="busy" @click="resume(data.run_id)">恢复任务</button><a class="btn" :href="'/api/quant/deliveries/' + data.run_id + '/export'" download="strategy.json">导出完整账本与来源</a></div>
  </section>
  <section v-if="data?.data?.admission" class="panel rep-section"><h2>本次数据准入</h2><span class="tag" :class="data.data.execution_status === 'COMPLETED' ? 'tag-cyan' : 'tag-warn'">{{ data.data.execution_status === 'COMPLETED' ? '计算完成 · 指标待独立核验' : '数据受限 · 未计算收益' }}</span><p class="condition-note">执行状态与指标验证等级分别记录。只有审核过的完整输入才能进入收益计算。</p><div v-for="(g,i) in data.data.admission.gaps" :key="i" class="bt-check-item"><strong>{{ g.domain }}</strong><p>{{ g.reason }} {{ g.instrument_id || '' }} {{ g.year || '' }}</p></div><p v-if="developer && data.data.admission.package_hash" class="num small strategy-input-hash">输入包 {{ data.data.admission.package_hash }}</p></section>
  <BacktestReport v-if="data?.data" :conditions="form" :report="data.data" :task-id="data.run_id" />
  <section v-if="developer && data?.data?.independent_check" class="panel rep-section"><h2>独立核对与离线复算</h2><div v-for="c in data.data.independent_check.checks" :key="c.basis" class="bt-check-item"><strong>{{ c.basis === 'strategy' ? '策略自身' : 'H00300全收益基准' }} · {{ c.status }}</strong><p>{{ c.note }}</p></div><div class="bt-actions"><button class="btn" :disabled="reproducing" @click="reproduce">{{ reproducing ? '离线复算中…' : '使用冻结原始输入离线复算' }}</button><span v-if="reproduction" class="tag">{{ reproduction.status }} · 同引擎复算</span></div><p v-if="reproductionError" class="error-text" role="alert">{{ reproductionError }}</p><p class="condition-note">复算一致说明可复现；独立参考一致才说明同口径交叉核对通过。两者分开记录，不自动升级验证等级。</p></section>
  <section v-if="data?.data?.ledgers" class="panel rep-section"><h2>现金、持仓与逐笔审计</h2><p class="condition-note">日终权益 = 现金 + 持仓原始收盘市值 + 应收现金及待上市股份；应收不作为可用现金。</p><details><summary>逐笔成交与拒单（{{ data.data.ledgers.strategy.orders.length }}）</summary><div class="table-scroll"><table class="data"><thead><tr><th>日期</th><th>证券</th><th>方向</th><th>股数</th><th>价格</th><th>费用</th><th>状态／原因</th></tr></thead><tbody><tr v-for="(o,i) in data.data.ledgers.strategy.orders" :key="i"><td>{{ o.session }}</td><td>{{ o.instrument }}</td><td>{{ o.side }}</td><td>{{ o.quantity }}</td><td>{{ o.price || '—' }}</td><td>{{ o.fee }}</td><td>{{ o.status }} {{ o.reason }}</td></tr></tbody></table></div></details><details v-if="developer"><summary>公司行为记录（{{ data.data.ledgers.strategy.events.length }}）</summary><pre class="small">{{ JSON.stringify(data.data.ledgers.strategy.events,null,2) }}</pre></details><details><summary>日终账本（{{ data.data.ledgers.strategy.daily.length }}）</summary><div class="table-scroll"><table class="data"><thead><tr><th>日期</th><th>现金</th><th>应收</th><th>权益</th><th>净值</th></tr></thead><tbody><tr v-for="d in data.data.ledgers.strategy.daily" :key="d.session"><td>{{ d.session }}</td><td>{{ d.cash }}</td><td>{{ d.receivables }}</td><td>{{ d.equity }}</td><td>{{ d.nav }}</td></tr></tbody></table></div></details></section>
</div></template>
